$postEvidenceDriftPath=Join-Path $workspace 'post-evidence-drift.txt';[IO.File]::WriteAllText($postEvidenceDriftPath,"later change`n",[Text.UTF8Encoding]::new($false));$replay=Invoke-Cli $workspace @('replay','-TransactionId',$transactionId,'-AsJson');$again=Invoke-Cli $workspace @('replay','-TransactionId',$transactionId,'-AsJson');$status=Read-Output (Invoke-Cli $workspace @('status','-TaskId','crash-task','-AsJson'))
