$sha256Workspace=Join-Path $temp 'sha256-workspace';[void][IO.Directory]::CreateDirectory($sha256Workspace);[IO.File]::WriteAllText((Join-Path $sha256Workspace '.gitignore'),".assistant/runtime/`n.harness/evidence/`nevidence-inputs/`ndocs/tasks/*/evidence.json`n",[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $sha256Workspace 'source.txt'),"sha256 baseline`n",[Text.UTF8Encoding]::new($false));$sha256Contract=Write-Contract $sha256Workspace 'sha256-task'
